def rollout(policy, env, max_turns=8):
    obs, info = env.reset()
    transcript = [obs]
    for turn in range(max_turns):
        action = policy.generate(transcript)      # tool call or final answer
        obs, reward, terminated, truncated, info = env.step(action)
        transcript += [action, obs]
        if terminated or truncated:
            break
    else:
        truncated = True                           # turn budget used up
    return transcript, reward, terminated, truncated
